import json, subprocess, warnings, os
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "डॉक्टर ने एज़ाथायोप्रिन, या सिक्स मर्कैप्टोप्यूरिन शुरू करने को कहा है? तो पहले, टी पी एम टी और एन यू डी टी फिफ्टीन, इन दो जीन के टेस्ट के बारे में जानिए. आखिर तक देखिए.",
 "ये दवाइयां, थायोप्यूरिन ग्रुप की हैं. इनका इस्तेमाल, आंतों की सूजन वाली बीमारी, यानी आई बी डी, जैसे क्रोन्स डिज़ीज़ और अल्सरेटिव कोलाइटिस में, और ब्लड कैंसर, ए एल एल में होता है. कुछ ऑटोइम्यून बीमारियों में भी.",
 "शरीर में, टी पी एम टी और एन यू डी टी फिफ्टीन एंज़ाइम, इन दवाओं को संभालते हैं. अगर इनके जीन में बदलाव हो, तो दवा का असर शरीर में ज़्यादा जमा हो जाता है. इससे बोन मैरो दब सकता है. व्हाइट ब्लड सेल बहुत कम, बार बार इन्फेक्शन, या ब्लीडिंग का खतरा.",
 "भारत का डेटा. उत्तर भारत के एक अस्पताल की स्टडी में, आई बी डी के एक सौ उन्नीस मरीज़ों में, लगभग ग्यारह प्रतिशत में, एन यू डी टी फिफ्टीन का बदलाव मिला. इनमें से आधे से ज़्यादा में, व्हाइट ब्लड सेल कम हुए. टी पी एम टी का बदलाव, सिर्फ चार प्रतिशत में मिला. इसलिए भारत में, दोनों जीन की जांच ज़रूरी मानी जाती है.",
 "रिपोर्ट में आमतौर पर तीन तरह के नतीजे आते हैं. नॉर्मल, यानी सामान्य डोज़. इंटरमीडिएट, यानी डॉक्टर कम डोज़ से शुरू कर सकते हैं. और पुअर मेटाबोलाइज़र, यानी बहुत कम डोज़, या दूसरी दवा. यह इंटरनेशनल सी पी आई सी गाइडलाइन के अनुसार है.",
 "किसे कराना चाहिए? जिन्हें एज़ाथायोप्रिन या सिक्स मर्कैप्टोप्यूरिन शुरू होने वाली है. आई बी डी और ए एल एल के मरीज़. और जिन्हें पहले, इन दवाओं से परेशानी हुई हो.",
 "जांच के लिए, ई डी टी ए ब्लड का सैंपल. फास्टिंग की ज़रूरत नहीं. जीन ज़िंदगी भर नहीं बदलते, इसलिए यह टेस्ट, आमतौर पर एक बार ही होता है.",
 "ध्यान रखें. नॉर्मल रिपोर्ट के बाद भी, डॉक्टर के कहे अनुसार, सी बी सी जांच चलती रहेगी. और अपनी डोज़, खुद से कभी न बदलें.",
 close_voice("क्या आपको या आपके परिवार में किसी को, एज़ाथायोप्रिन दी गई है?"),
]
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/tpmtr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/tpmt_{i}.wav"],check=True); f=f"/tmp/tpmt_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/tpmt_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
